import runpy
from pathlib import Path
import hashlib
root = Path.cwd()
files = ['release.md','001_initial.sql','002_up.sql','002_down.sql','old_reader.py','new_reader.py']
before = {f: hashlib.sha256((root/f).read_bytes()).hexdigest() for f in files}
helper = runpy.run_path('.agents/skills/friday/scripts/sqlite_matrix.py')
recipe = {
 'phases': [
  {'name':'initial', 'files':['001_initial.sql'], 'sql':"INSERT INTO users (id, name) VALUES (1, 'Original'), (2, 'Unchanged');"},
  {'name':'up before application replacement', 'files':['002_up.sql']},
  {'name':'up after representative new-schema writes / old binary rollback restart', 'sql':"INSERT INTO users (id, display_name) VALUES (3, 'New user'); UPDATE users SET display_name = 'Updated by new schema' WHERE id = 1;"},
  {'name':'down after rollback', 'files':['002_down.sql']}
 ],
 'checks': {
  'old reader': {'python_file':'old_reader.py','constant':'QUERY'},
  'new reader': {'python_file':'new_reader.py','constant':'QUERY'}
 }
}
result = helper['matrix'](recipe, root, timeout=5)
print(helper['format_result'](result))
assert result['complete']
expected = [
 {'old reader': ('name', [(1,'Original'),(2,'Unchanged')]), 'new reader': None},
 {'old reader': None, 'new reader': ('display_name', [(1,'Original'),(2,'Unchanged')])},
 {'old reader': None, 'new reader': ('display_name', [(1,'Updated by new schema'),(2,'Unchanged'),(3,'New user')])},
 {'old reader': ('name', [(1,'Updated by new schema'),(2,'Unchanged'),(3,'New user')]), 'new reader': None}
]
assert len(result['phases']) == len(expected)
for phase, wants in zip(result['phases'], expected):
 for reader, want in wants.items():
  check = phase['checks'][reader]
  if want is None:
   assert not check['ok'] and 'no such column' in check['error'], check
  else:
   column, rows = want
   assert check['ok'] and not check['truncated'], check
   assert list(check['columns']) == ['id', column], check
   assert sorted(map(tuple, check['rows'])) == rows, check
assert before == {f: hashlib.sha256((root/f).read_bytes()).hexdigest() for f in files}
print('PASS: all reader outcomes, column labels, surviving row values, and release-file preservation asserted.')

